 IF NOT EXISTS(SELECT 1 FROM public.movement_offers o JOIN public.vehicles v ON v.id=o.vehicle_id
  WHERE o.id=a.movement_offer_id AND o.status='accepted' AND o.vehicle_id=p.vehicle_id
